SELECT COUNT(*) 
  FROM tb_dept 
WHERE dept_code = #{deptCode}

SELECT dept_code AS deptCode, parent_code AS parentCode, dept_name AS deptName, sort_order AS sortOrder, use_yn AS useYn, created_at AS createdAt, updated_at AS updatedAt FROM tb_dept where 1=1 and use_yn = 'Y'
AND parent_code = #{parent_code}
ORDER BY sort_order ASC, dept_name ASC

mapper.update:
UPDATE tb_dept
dept_name = #{deptName}, sort_order = #{sortOrder}, use_yn = #{useYn}, parent_code = #{parentCode}, updated_at = NOW()
WHERE dept_code = #{deptCode}
